import{_ as t,a8 as o,o as r,c as n,ah as x,K as l}from"./chunks/framework.D31WLDJp.js";import"./chunks/theme.CP9whvzN.js";const g=JSON.parse('{"title":"openpyxl 与大文件 xlsx 处理坑体系","description":"","frontmatter":{"type":"lesson","scope":"global","created":"2026-09-12T00:00:00.000Z","updated":"2026-09-12T00:00:00.000Z","tags":["lesson","openpyxl","xlsx","excel","坑"]},"headers":[],"relativePath":"vault/Memory/Lessons/openpyxl与大文件xlsx处理坑.md","filePath":"vault/Memory/Lessons/openpyxl与大文件xlsx处理坑.md","lastUpdated":1789374053000}'),d={name:"vault/Memory/Lessons/openpyxl与大文件xlsx处理坑.md"};function i(p,e,c,h,_,m){const a=o("NolebaseGitContributors"),s=o("NolebaseGitChangelog");return r(),n("div",null,[e[0]||(e[0]=x('<h1 id="openpyxl-与大文件-xlsx-处理坑体系" tabindex="-1">openpyxl 与大文件 xlsx 处理坑体系 <a class="header-anchor" href="#openpyxl-与大文件-xlsx-处理坑体系" aria-label="Permalink to “openpyxl 与大文件 xlsx 处理坑体系”">​</a></h1><p>来源：帮老适任职期间（2026-07~08）反复踩坑的总结，均为实测结论。</p><h2 id="save-会毁掉含大量嵌入图片的-xlsx" tabindex="-1">save() 会毁掉含大量嵌入图片的 xlsx <a class="header-anchor" href="#save-会毁掉含大量嵌入图片的-xlsx" aria-label="Permalink to “save() 会毁掉含大量嵌入图片的 xlsx”">​</a></h2><p>282–295MB、含 412 media/703 图片锚点的 xlsx，经 openpyxl 读写后 media 被逐锚点重嵌为 701 个独立 media，文件涨到 490MB。根因：openpyxl 重写整个 zip 时无法保留原 media 引用结构。<strong>解法：只改 <code>xl/worksheets/sheetN.xml</code>，其余 zip 部件按字节原样复制</strong>；单元格替换用边界安全正则 <code>&lt;c\\b(?:(?!&lt;\\/c&gt;).)*?&lt;/c&gt;|&lt;c\\b[^&gt;]*\\/&gt;</code>，改完用 ElementTree 逐格 diff 校验「仅目标变化、零数据丢失」。openpyxl 保存还会丢 DISPIMG 图片。</p><h2 id="写「正被-excel-打开」的文件会截断丢数据" tabindex="-1">写「正被 Excel 打开」的文件会截断丢数据 <a class="header-anchor" href="#写「正被-excel-打开」的文件会截断丢数据" aria-label="Permalink to “写「正被 Excel 打开」的文件会截断丢数据”">​</a></h2><p>openpyxl save 先以 &#39;w&#39; 截断再报 PermissionError，此时 .bak 也不含丢失行（备份在写入前）。<strong>安全保存 = 先写 .tmp 再 <code>os.replace</code> 原子替换</strong>；写前检查 <code>~$</code> 锁文件；占用时只提示不截断。</p><h2 id="windows-预览面板锁文件的三级兜底" tabindex="-1">Windows 预览面板锁文件的三级兜底 <a class="header-anchor" href="#windows-预览面板锁文件的三级兜底" aria-label="Permalink to “Windows 预览面板锁文件的三级兜底”">​</a></h2><p>① <code>os.replace</code> 失败但 <code>open(&quot;wb&quot;)</code> 字节复制可能成功；② 完全锁死时对预览池文件实时编辑再字节同步回原名；③ 字节级复制覆盖是可靠兜底。另：openpyxl 对合并单元格非左上角赋值报 MergedCell read-only，须先 <code>ws.unmerge_cells</code>。</p><h2 id="delete-rows-是高危操作" tabindex="-1">delete_rows 是高危操作 <a class="header-anchor" href="#delete-rows-是高危操作" aria-label="Permalink to “delete_rows 是高危操作”">​</a></h2><p>降序删+改名后数据错位/重复；删除后原行上移导致后续写入覆盖有效数据；且不同步调整 freeze_panes（删说明行后把首条数据冻住）。<strong>最稳做法：读全行→按规则筛选→删光所有行→重写</strong>，并复查 freeze_panes/auto_filter 引用。</p><h2 id="其他" tabindex="-1">其他 <a class="header-anchor" href="#其他" aria-label="Permalink to “其他”">​</a></h2><ul><li><strong>腾讯文档编辑器写坏 styles.xml</strong>：openpyxl 报 <code>expected Fill</code>，读取只能走 zipfile+XML 绕过样式；列定位按表头名称（列位会漂移）。</li><li><strong>editor_sdk 类 MCP 打不开大文件</strong>：<code>open_file</code> 异步流式、sheet 工具一直 &quot;No workbook open&quot;；读超大 xlsx（324MB）用手动 zip+XML 解析。</li><li><strong>.doc 解码内容含非法控制字符</strong>：olefile 产生 <code>\\x0b</code>/<code>\\x01</code> → openpyxl <code>IllegalCharacterError</code>，导出前清洗 <code>[\\x00-\\x08\\x0b\\x0c\\x0e-\\x1f]</code>。</li></ul><h2 id="含图-xlsx-的图像安全修改法-固定流程" tabindex="-1">含图 xlsx 的图像安全修改法（固定流程） <a class="header-anchor" href="#含图-xlsx-的图像安全修改法-固定流程" aria-label="Permalink to “含图 xlsx 的图像安全修改法（固定流程）”">​</a></h2><ol><li>zipfile 打开，只重写目标 sheet XML（+styles.xml 如需加样式）；</li><li>其余部件逐字节复制；</li><li>改完 ElementTree 逐格 diff 验证；</li><li>永远先做写入前锁检查 + .tmp 原子替换。</li></ol>',14)),l(a),l(s)])}const y=t(d,[["render",i]]);export{g as __pageData,y as default};
